import keeps_recurring from "./keeps_recurring";
import which_system from "./which_system";
import select_by_flags from "./select_by_flags";
import group_count from "./group_count";
import count_if from "./count_if";
import halve from "./halve";
import is_small from "./is_small";
---
description: A synthesized program.
returns: Num
---
function incident_overview(alerts) -> { breakdown: Dict<Num>, count: Num, shifts_needed: Num }

  recurring = [keeps_recurring(x) for x in alerts]
  systems = map(x => which_system(x), alerts)
  shortlist = select_by_flags(alerts, recurring)
  if shortlist is empty:
      breakdown = {}
  else:
      components = [which_system(x) for x in shortlist]
      breakdown = group_count(components)
  is_storage = for each l in systems: l == "storage"          # exact: use code
  count = carry a count through is_storage, starting at 0: count_if(acc, item)
  shifts_needed = repeat at most 8 times, until is_small(state): state = halve(state), starting from count
  return { breakdown, count, shifts_needed }

import mentions_side_effects from "./mentions_side_effects";
import kind_of_study from "./kind_of_study";
import in_adults from "./in_adults";
import select_by_flags from "./select_by_flags";
import group_count from "./group_count";
---
description: A synthesized program.
returns: Num
---
function abstract_triage(abstracts) -> { by_topic: Dict<Num>, by_designs: Dict<Num>, share: Num }

  let side_effects = for x in abstracts do mentions_side_effects(x)
  let designs = for x in abstracts do kind_of_study(x)
  let adults_only = for x in abstracts do in_adults(x)
  subset = select_by_flags(abstracts, adults_only)
  if subset is empty:
      by_topic = {}
  else:
      study_kinds = [kind_of_study(x) for x in subset]
      by_topic = group_count(study_kinds)
  by_designs = group_count(designs)
  share = share of true in side_effects, rounded to 2 decimals     # exact
  return { by_topic, by_designs, share }

